function pageIdentifier(value) {
  if (
    typeof value !== "string" ||
    !/^(?:[a-f0-9]{32}|[a-f0-9]{8}(?:-[a-f0-9]{4}){3}-[a-f0-9]{12})$/i.test(value)
  ) {
    throw new Error("Set the parent Notion page ID");
  }
  return value.toLowerCase().replaceAll("-", "");
}

function normalizeAudio(event) {
  const name = event.name;
  const mimeType = event.mimeType;
  if (typeof name !== "string" || typeof mimeType !== "string")
    throw new Error("The Drive event omitted the file metadata");
  const extensionSupported = /\.(?:flac|mp3|mp4|mpeg|mpga|m4a|ogg|wav|webm)$/i.test(name);
  const mediaSupported =
    mimeType.startsWith("audio/") ||
    /^(?:application\/octet-stream|video\/(?:mp4|webm))$/.test(mimeType);
  if (!extensionSupported || !mediaSupported) return null;
  if (typeof event.fileId !== "string" || !/^[A-Za-z0-9_-]{2,512}$/.test(event.fileId)) {
    throw new Error("The Drive event omitted the recording ID");
  }
  if (
    event.size != null &&
    (typeof event.size !== "string" ||
      !/^\d+$/.test(event.size) ||
      Number(event.size) < 1 ||
      Number(event.size) > 25_000_000)
  ) {
    throw new Error("The recording must contain between 1 and 25,000,000 bytes");
  }
  return { id: event.fileId, name, mimeType, size: event.size == null ? null : Number(event.size) };
}

export default ({ parentId, events }) => {
  const recordings = new Map();
  for (const event of events) {
    if (event.eventType !== "file_created" || event.itemType !== "file") continue;
    const audio = normalizeAudio(event);
    if (audio) recordings.set(audio.id, audio);
  }
  return { parent: pageIdentifier(parentId), recordings: [...recordings.values()] };
};

