function audioInput(recording, received) {
  if (
    received.fileId !== recording.id ||
    received.mimeType !== recording.mimeType ||
    !Number.isSafeInteger(received.sizeBytes) ||
    received.sizeBytes < 1 ||
    received.sizeBytes > 25_000_000 ||
    (recording.size !== null && recording.size !== received.sizeBytes) ||
    typeof received.transitUrl !== "string" ||
    !/^https:\/\/[^/\s]+\//.test(received.transitUrl)
  ) {
    throw new Error("The Drive download did not match the selected recording");
  }
  return { name: recording.name, mimetype: received.mimeType, url: received.transitUrl };
}

export default ({ recording, transfer }) => ({ file: audioInput(recording, transfer) });

