function transcriptionInput(text, now) {
  if (typeof text !== "string" || !text.trim())
    throw new Error("OpenAI returned an empty transcription");
  return [
    {
      role: "user",
      content: JSON.stringify({ todayUtc: now.toISOString().slice(0, 10), transcript: text }),
    },
  ];
}

export default ({ transcript }) => ({ input: transcriptionInput(transcript.text, new Date()) });

