function richText(content) {
  return { type: "text", text: { content } };
}

function summaryPage(response, listFields) {
  if (response?.status !== "completed" || response.error || !Array.isArray(response.output)) {
    throw new Error("OpenAI did not complete the structured summary");
  }
  const content = response.output
    .filter((item) => item.type === "message" && item.role === "assistant")
    .flatMap((item) => item.content ?? []);
  if (
    content.length !== 1 ||
    content[0].type !== "output_text" ||
    typeof content[0].text !== "string"
  ) {
    throw new Error("OpenAI did not provide one structured summary");
  }
  const summary = JSON.parse(content[0].text).audioContentSummary;
  if (
    !summary ||
    typeof summary.title !== "string" ||
    !summary.title.trim() ||
    summary.title.length > 1900 ||
    typeof summary.summary !== "string" ||
    !summary.summary.trim() ||
    typeof summary.sentiment !== "string" ||
    !listFields.every(
      (key) =>
        Array.isArray(summary[key]) && summary[key].every((item) => typeof item === "string"),
    )
  ) {
    throw new Error("OpenAI returned an invalid title, summary or analysis field");
  }

  const paragraphs = [];
  let part = "";
  for (const character of summary.summary) {
    if (part.length + character.length > 1900) {
      paragraphs.push(richText(part));
      part = "";
    }
    part += character;
  }
  if (part) paragraphs.push(richText(part));
  if (paragraphs.length > 100) throw new Error("The summary exceeds the Notion page request limit");
  return {
    title: summary.title.trim(),
    children: [
      { object: "block", type: "heading_1", heading_1: { rich_text: [richText("Summary")] } },
      { object: "block", type: "paragraph", paragraph: { rich_text: paragraphs } },
    ],
  };
}

export default ({ result }) =>
  summaryPage(result, [
    "main_points",
    "action_items",
    "follow_up",
    "stories",
    "references",
    "arguments",
    "related_topics",
  ]);

