function pageIdentifier(value) {
  if (
    typeof value !== "string" ||
    !/^(?:[a-f0-9]{32}|[a-f0-9]{8}(?:-[a-f0-9]{4}){3}-[a-f0-9]{12})$/i.test(value)
  ) {
    throw new Error("Set the parent Notion page ID");
  }
  return value.toLowerCase().replaceAll("-", "");
}

function pageReceipt(receipt, parentId, driveFileId) {
  if (
    receipt?.object !== "page" ||
    pageIdentifier(receipt.parent?.page_id) !== pageIdentifier(parentId) ||
    typeof receipt.url !== "string" ||
    !receipt.url.startsWith("https://")
  ) {
    throw new Error(
      "Notion did not confirm the new page under the selected parent. Check Notion before retrying.",
    );
  }
  return { driveFileId, pageId: pageIdentifier(receipt.id), url: receipt.url };
}

export default ({ parentId, fileId, receipt }) => ({
  result: pageReceipt(receipt, parentId, fileId),
});
